return-response.set-body:
@{
        var auth = context.LastError.Source == "validate-jwt";
        var throttled = context.LastError.Reason == "RateLimitExceeded";
        return new JObject(new JProperty("type", "about:blank"),
          new JProperty("title", auth ? "A valid delegated gateway token is required." : "MCP gateway request failed."),
          new JProperty("status", auth ? 401 : (throttled ? 429 : 502)),
          new JProperty("code", auth ? "gateway_unauthorized" : (throttled ? "gateway_throttled" : "mcp_gateway_error"))
        ).ToString(Newtonsoft.Json.Formatting.None);
      }
